import{_ as o,c as i,o as e,ae as n}from"./chunks/framework.BQlYxExx.js";const r="/images/sprint1.png",t="/images/sprint2.png",y=JSON.parse('{"title":"Zarządzanie projektem / Podział zadań w sprintach","description":"","frontmatter":{},"headers":[],"relativePath":"sprinty.md","filePath":"sprinty.md"}'),l={name:"sprinty.md"};function s(z,a,c,p,d,w){return e(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="zarzadzanie-projektem-podział-zadan-w-sprintach" tabindex="-1">Zarządzanie projektem / Podział zadań w sprintach <a class="header-anchor" href="#zarzadzanie-projektem-podział-zadan-w-sprintach" aria-label="Permalink to &quot;Zarządzanie projektem / Podział zadań w sprintach&quot;">​</a></h1><p>Zadania projektowe zostały podzielone na cztery sprinty, realizowane w metodyce Scrum. Poniżej przedstawiono plan sprintów oraz szczegółową dokumentację ich realizacji, włącznie z Retrospektywami.</p><h2 id="_7-1-sprint-1" tabindex="-1">7.1. SPRINT 1 <a class="header-anchor" href="#_7-1-sprint-1" aria-label="Permalink to &quot;7.1. SPRINT 1&quot;">​</a></h2><p><strong>Planowane Zadania:</strong></p><ul><li>Inicjalizacja i konfiguracja projektu</li><li>Implementacja widoku strony lądowania (Landing Page)</li><li>Implementacja systemu autoryzacji</li><li>Stworzenie logiki panelu administracyjnego</li><li>Implementacja pełnego cyklu CRUD dla Zwierząt</li></ul><p><strong>Realizacja i Postęp</strong> SPRINT 1 skupił się na fundamentach technicznych i bazowych modelach danych.</p><ul><li><strong>Inicjalizacja i konfiguracja</strong>: Pomyślnie wdrożono kontenerowe środowisko deweloperskie Docker-compose (Laravel, PostgreSQL, Redis, Mailpit). Skonfigurowano Vite dla frontendu i podstawowe skrypty automatyzacji (Makefile).</li><li><strong>Backend</strong>: Zaimplementowano modele User i Animal, ich migracje oraz pełny cykl CRUD dla zwierząt (API endpoints).</li><li><strong>Frontend</strong>: Stworzono pierwszą wersję responsywnego Landing Page oraz bazowy layout aplikacji.</li><li><strong>Autoryzacja i Admin</strong>: Zainicjowano strukturę autoryzacji (tylko backendowe trasy logowania/rejestracji) i rozpoczęto tworzenie logiki dla panelu administracyjnego.</li><li><strong>Status</strong>: Wszystkie zaplanowane zadania zostały zrealizowane (100 procent ukończenia).</li></ul><p><strong>Dokumentacja Postępu (Trello)</strong> Postęp prac w SPRINT 1 został udokumentowany na tablicy projektowej.</p><p><img src="'+r+'" alt="Tablica projektu - SPRINT 1"><em>Rysunek 5: Tablica projektu - SPRINT 1</em></p><p><strong>Retrospektywa SPRINT 1</strong> Uczestnicy: Krzysztof Kozyra (Project Manager, Backend), Tomasz Rebizant (Frontend).</p><ul><li><strong>Co poszło dobrze (Keep)</strong>: Szybka inicjalizacja środowiska deweloperskiego (Docker) i efektywna praca Krzysztofa w warstwie Backend. Tomasz szybko dostarczył bazowy layout (Landing Page).</li><li><strong>Co wymaga poprawy (Less)</strong>: Wystąpiły drobne nieporozumienia w komunikacji między Backendem a Frontendem, co do nazw endpointów API dla CRUD zwierząt. Zauważono brak ujednoliconego formatu danych.</li><li><strong>Nowe pomysły (More)</strong>: Konieczność wdrożenia narzędzia do wizualizacji API (np. Swagger/OpenAPI) w celu szybszej integracji warstw.</li><li><strong>Działania korygujące (Action Items do SPRINT 2)</strong>: Krzysztof dodaje zadanie &quot;Implementacja bazowej dokumentacji OpenAPI&quot; do Backlogu SPRINTU 2. Tomasz sprawdza czytelność i jednolitość stylów Vue.js po pierwszym sprincie.</li></ul><h2 id="_7-2-sprint-2" tabindex="-1">7.2. SPRINT 2 <a class="header-anchor" href="#_7-2-sprint-2" aria-label="Permalink to &quot;7.2. SPRINT 2&quot;">​</a></h2><p><strong>Planowane Zadania:</strong></p><ul><li>Implementacja pełnego cyklu CRUD dla Tagów i Schronisk</li><li>Konfiguracja i refaktoryzacja routingu</li><li>Implementacja głównego panelu użytkownika (Dashboard)</li><li>Implementacja pełnego cyklu CRUD dla Administratorów i Użytkowników</li><li>Stworzenie mechanizmów crawlera i scrapera</li><li>Częściowa praca nad systemem obsługi obrazów (Spatie, Scrap images, links, conversion)</li><li>Implementacja widoku szczegółów wybranego zwierzaka</li></ul><p><strong>Realizacja i Postęp</strong> SPRINT 2 był najbardziej intensywny pod kątem modelowania danych i kluczowych funkcjonalności.</p><ul><li><strong>Backend</strong>: Ukończono cykle CRUD dla Shelter i Tag. Rozpoczęto prace nad logiką crawlera/scrapera (wybór bibliotek, struktura pobierania). Ukończono CRUD dla Administratorów i Użytkowników.</li><li><strong>Frontend</strong>: Ukończono widok Dashboard oraz widok szczegółów zwierzęcia. Przeprowadzono refaktoryzację routingu.</li><li><strong>Obrazy</strong>: Uruchomiono wstępne pobieranie obrazów za pomocą scrapera, ale bez pełnej implementacji konwersji i przechowywania (Spatie MediaLibrary).</li><li><strong>Status</strong>: Ze względu na dużą liczbę zadań związanych ze scraperem, nie zrealizowano zadania „Stworzenie mechanizmów crawlera i scrapera” w pełni (ukończono na poziomie 60%). Zadanie to zostało przesunięte do SPRINTU 3.</li></ul><p><strong>Dokumentacja Postępu (Trello)</strong> Postęp prac w SPRINT 2.</p><p><img src="'+t+'" alt="Tablica projektu - SPRINT 2"><em>Rysunek 6: Tablica projektu - SPRINT 2</em></p><p><strong>Retrospektywa SPRINT 2</strong> Uczestnicy: Krzysztof Kozyra, Tomasz Rebizant.</p><ul><li><strong>Co poszło dobrze (Keep)</strong>: Szybka implementacja Dashboardu i widoków szczegółów. Modele Shelter i Tag zostały zaimplementowane sprawnie.</li><li><strong>Co wymaga poprawy (Less)</strong>: Zadanie związane ze scraperem i crawlerem było zbyt obszerne i niedoszacowane (przypominamy: estymacja wynosiła 12 godzin). Przeciążenie Backendu spowodowało, że część pracy nad obsługą obrazów również się opóźniła.</li><li><strong>Nowe pomysły (More)</strong>: Konieczność rozbicia dużych zadań (Epiców) na mniejsze, bardziej zarządzalne części w przyszłych sprintach.</li><li><strong>Działania korygujące (Action Items do SPRINT 3)</strong>: Pełna implementacja scrapera i crawlera zostaje podzielona na mniejsze taski i przeniesiona do SPRINTU 3. Wprowadzamy zasadę, że jedno zadanie nie może mieć estymacji wyższej niż 8 roboczogodzin.</li></ul><h2 id="_7-3-metryki-zwinne-velocity" tabindex="-1">7.3. Metryki Zwinne (Velocity) <a class="header-anchor" href="#_7-3-metryki-zwinne-velocity" aria-label="Permalink to &quot;7.3. Metryki Zwinne (Velocity)&quot;">​</a></h2><p>W celu oceny tempa pracy i realności ukończenia projektu w terminie, obliczono wskaźnik Velocity (prędkość zespołu) na podstawie roboczogodzin (średnia z estymacji) dla zadań, które zostały ukończone w 100% w SPRINT 1 i SPRINT 2.</p><p><strong>Obliczenie Velocity</strong></p><ul><li><p>Suma godzin SPRINT 1 (Ukończony 100%): 27:30:00</p></li><li><p>Suma godzin SPRINT 2 (Zadania ukończone 100%): 53:00:00</p></li><li><p><strong>Średnia Velocity (S1 + S2)</strong>: Velocity = (27:30:00 + 53:00:00) / 2 = 40:15:00 roboczogodzin/sprint</p></li></ul><p><strong>Wnioski</strong> Średnie Velocity na poziomie 40 godzin i 15 minut będzie używane do planowania i monitorowania SPRINTÓW 3 i 4. Wartość ta pokazuje, że zespół jest w stanie zrealizować około 20 roboczogodzin więcej niż pierwotna estymacja (71 godzin) w cyklu 2 tygodni (na 2 osoby), co sugeruje, że zadania w SPRINTACH 3 i 4 są w zakresie możliwości zespołu.</p><h2 id="_7-4-sprint-3" tabindex="-1">7.4. SPRINT 3 <a class="header-anchor" href="#_7-4-sprint-3" aria-label="Permalink to &quot;7.4. SPRINT 3&quot;">​</a></h2><ul><li>Implementacja pełnego cyklu CRUD dla Preferencji użytkownika</li><li>Implementacja mechanizmu weryfikacji ogłoszeń przez administratora</li><li>Poprawki wizualne (zmiana logo aplikacji)</li><li>Implementacja algorytmu dopasowywania zwierząt do preferencji</li><li>Implementacja widoków autoryzacji</li><li>Naprawa błędów w logice (panel administracyjny)</li></ul><h2 id="_7-5-sprint-4" tabindex="-1">7.5. SPRINT 4 <a class="header-anchor" href="#_7-5-sprint-4" aria-label="Permalink to &quot;7.5. SPRINT 4&quot;">​</a></h2><ul><li>Stworzenie systemu obsługi i przechowywania obrazów (Dalszy etap developmentu)</li><li>Użycie API na potrzeby obsługi geolokalizacji</li><li>Implementacja mechanizmu dodawania/usuwania z ulubionych zwierząt</li><li>Przeprowadzenie refaktoryzacji i naprawa błędów</li></ul>',29)])])}const u=o(l,[["render",s]]);export{y as __pageData,u as default};
